export function prorateDowngrade(sub: Subscription, at: Date): number {
  const remaining = daysLeft(sub.period, at);
  return round((sub.price * remaining) / sub.period.days);
}

export function settleDowngrade(invoice: Invoice, sub: Subscription, at: Date): Invoice {
  return applyCredit(invoice, -prorateDowngrade(sub, at));
}

export function prorateDowngrade(sub: Subscription, at: Date): number {
  const remaining = daysLeft(sub.period, at);
  return -round((sub.price * remaining) / sub.period.days);
}
